// core/deck/startup.hpp — Claude Code's startup dialogs read off the pty stream (lib/startupprompts.js), and the
// home-folder trust prompt's reader (main.js spawnTile's `trustWatch`), ported. PURE.
// Checked against core/test/fixtures/deck/startup.json (generated by running lib/startupprompts.js over the
// recorded dialogs in test/fixtures/startup-*.raw and synthetic ones).
#pragma once
#include "../third_party/nlohmann/json.hpp"
#include <functional>
#include <string>
#include <utility>
#include <vector>

namespace deck { namespace core {

using json = nlohmann::json;

std::string startupScreenText(const std::string& d);                              // screenText
std::pair<std::string, std::string> splitIncomplete(const std::string& s);        // [complete, held back]
using ExistsFn = std::function<bool(const std::string&)>;
// { kind: 'settings-warning' | 'trust' | 'mcp' | 'other', title, continueSelected?, rules?, errors?, file? } or null
json classifyStartup(const std::string& text, const ExistsFn& exists = nullptr);
std::string describeWarning(const json& prompt);

class StartupWatch {
 public:
  explicit StartupWatch(double now, ExistsFn exists = nullptr) : since(now), lastDataAt(now), exists_(std::move(exists)) {}
  void feed(const std::string& d, double now);
  void keySent() { text_.clear(); prompt = json(); }
  void finish() { done = true; text_.clear(); carry_.clear(); prompt = json(); }
  json waitingOn(double now) const;                                               // the dialog it sits on, or null
  bool wantsContinue(bool enabled, double lastKeyAt) const;
  double since, lastDataAt;
  json prompt;
  int answers = 0;
  bool pending = false, done = false;
 private:
  ExistsFn exists_;
  std::string text_, carry_;
};

// main.js trustWatch: the text kept (ANSI CSI removed, the last 8000 characters), and what it says
std::string trustAppend(const std::string& text, const std::string& chunk);
bool trustPromptSeen(const std::string& text);       // /Quick\s*safety\s*check|Yes,\s*I\s*trust\s*this\s*folder/
bool trustOptionSeen(const std::string& text);       // /Yes,\s*I\s*trust\s*this\s*folder/
std::string trustMarkerLine(const std::string& text);   // "yes" | "no" | "" — the LAST marked option

}}  // namespace deck::core
